/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    CardTemplate, CARD_MAX_COPIES, RARITY_CHANCES, CARD_LEVELS, CARD_MASTERY_LEVELS, CARD_MASTERY_EFFECT_LEVELS, CARD_TEMPLATES, CARDS_BY_RARITY (+2 more)
 * depends    —
 * used by    src/data/cards/index, src/data/index, src/knowledge/compartments/cards, src/knowledge/compartments/masteries, src/mechanics/calculators/specs-generated, src/mechanics/effective-paths/input-ranges (+2 more)
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
export interface CardTemplate {
  id: string
  name: string
  // Static human-readable description of the card's effect (doesn't change per level)
  description: string
  rarity: 'common' | 'rare' | 'epic'
  // Type for all levels
  levelType: 'percent' | 'flat' | 'duration' | 'multi'
  // Numeric values for each level (index 0 -> level 1)
  levelValues: number[]
  // Name for mastery
  masteryName: string
  // Description for mastery
  masteryDescription: string
  // Type for all mastery levels
  masteryType: 'percent' | 'flat' | 'duration' | 'multi'
  /*
   * Numeric values for each mastery level, **index 0 -> mastery level 0**.
   *
   * Note the offset differs from `levelValues` above, which is index 0 -> level 1.
   * Unlocking a mastery grants its level-0 effect immediately; the nine mastery
   * LAB levels then raise it, so ten values cover levels 0-9. The wiki's Card
   * Mastery Overview table is headed 0-9 for the same reason, while its lab
   * time/coin table runs 1-9.
   *
   * This comment read "index 0 -> mastery 1" until 2026-08-17 and was off by
   * one. `buildCardRegistry` in platform's chart spreadsheet library followed
   * it, labelling every mastery row one level too high — inventing a level 10
   * and omitting level 0.
   */
  masteryValues: number[]
}

export const CARD_MAX_COPIES = 80 // Total copies required to reach max level (level 7)

